1	/* vplat: one newlib syscall layer that works on EVERY engine.
2	 *
3	 * Replaces -lgloss_vh (semihosting) so a single ELF runs unmodified on
4	 * QEMU (fast), vsim (cycle) and across a hybrid handoff. It only touches
5	 * channels both engines model at the same addresses:
6	 *
7	 *   stdio (fd 0-2)  ATCUART100 UART2: THR @0xf0300020, LSR @0xf0300034.
8	 *                   QEMU: serial_mm_init(UART2+0x20, shift 2) = serial_hd(0);
9	 *                   vsim: src/platform/uart.hpp (vsim repo) -> host stdout.
10	 *   exit            SimControl @0xe0080000: u32 exit code (<256).
11	 *                   vsim: sim_control.hpp; QEMU: hw/riscv/andes_ae350.c
12	 *                   (sim_ctrl_write).
13	 *   file io (fd>2)  the SimControl syscall WINDOW @0xe0080800: eight u64
14	 *                   arg/result slots + a data area for payloads, doorbell
15	 *                   @0xe0080028. Served host-side (vsim: sim_control.hpp
16	 *                   dispatch_window; QEMU: andes_ae350.c's mirror).
17	 *
18	 * The window lives in DEVICE space (PMA-uncached on every engine), so the
19	 * whole exchange is coherent by construction: no guest cache line can
20	 * shadow a host write. Its predecessor -- a magicmem block in cacheable
21	 * RAM that the host peeked/poked by backdoor -- broke on any core with a
22	 * private write-back L2 (ax66 PL2C): the guest read its own stale copy of
23	 * the host's result, and no guest-side CCTL sequence can fix that (the
24	 * VA-scoped forms trap on RVH cores, the ALL forms drop unrelated dirty
25	 * lines). Marshaling payloads through the window costs a few uncached
26	 * copies per call; correctness on every cache hierarchy is worth it.
27	 *
28	 * No semihosting, no ecall, and no "which engine am I on" probe -- hybrid
29	 * migrates the running process between engines, so any boot-time detection
30	 * would go stale at the handoff. Every call must be engine-blind.
31	 */
32	
33	#include <stdint.h>
34	#include <stddef.h>
35	#include <sys/stat.h>
36	#include <unistd.h>
37	
38	/* ---- UART2 (console) ------------------------------------------------- */
39	
40	#define UART_THR (*(volatile uint32_t*) 0xf0300020UL)
41	#define UART_LSR (*(volatile uint32_t*) 0xf0300034UL)
42	#define UART_LSR_THRE 0x20u
43	
44	static void uart_putc(char c)
45	{
46	  while (!(UART_LSR & UART_LSR_THRE))
47	    ;
48	  UART_THR = (uint32_t) (unsigned char) c;
49	}
50	
51	/* ---- SimControl: exit + syscall window -------------------------------- */
52	
53	#define SIM_EXIT_ADDR   0xe0080000UL
54	#define SYSCALL_GO_ADDR 0xe0080028UL
55	
56	/* Window layout -- must match the hosts (vsim src/platform/sim_control.hpp
57	 * SYSCALL_WINDOW_*; QEMU hw/riscv/andes_ae350.c ANDESIM_SYSCALL_*):
58	 * eight u64 arg/result slots, then the payload data area. All guest
59	 * accesses are u64 loads/stores (the access width every engine already
60	 * proves out on the legacy 0x10 doorbell). */
61	#define WIN_SLOTS ((volatile uint64_t*) 0xe0080800UL)
62	#define WIN_DATA_VA 0xe0080840UL
63	#define WIN_DATA_SIZE (0x800u - 0x40u) /* 1984 bytes, 8-aligned */
64	
65	/* HTIF syscall numbers -- must match the table in the vsim repo's
66	 * src/platform/sim_control.hpp (and the QEMU mirror device). */
67	#define VH_SYS_GETTIMEOFDAY 5
68	#define VH_SYS_OPEN         6
69	#define VH_SYS_WRITE        7
70	#define VH_SYS_GETCWD       8
71	#define VH_SYS_LSEEK        9
72	#define VH_SYS_READ         10
73	#define VH_SYS_FLEN         11
74	#define VH_SYS_CLOSE        12
75	#define VH_SYS_ACCESS       13
76	#define VH_SYS_FACCESSAT    14
77	#define VH_SYS_FSTAT        15
78	#define VH_SYS_FSTATAT      16
79	#define VH_SYS_LINK         17
80	#define VH_SYS_LSTAT        18
81	#define VH_SYS_STAT         19
82	#define VH_SYS_OPENAT       20
83	#define VH_SYS_RENAME       21
84	#define VH_SYS_UNLINK       22
85	
86	/* Copy guest memory into the window data area (u64 stores only; the final
87	 * partial word over-stores into window slack, which is scratch). `woff` is
88	 * a byte offset into the data area and must be 8-aligned. */
89	static void win_store(size_t woff, const void* src, size_t len)
90	{
91	  const unsigned char* s = (const unsigned char*) src;
92	  volatile uint64_t* w = (volatile uint64_t*) (WIN_DATA_VA + woff);
93	  while (len) {
94	    size_t n = len < 8 ? len : 8;
95	    uint64_t word = 0;
96	    for (size_t i = 0; i < n; ++i)
97	      word |= (uint64_t) s[i] << (8 * i);
98	    *w++ = word;
99	    s += n;
100	    len -= n;
101	  }
102	}
103	
104	/* Copy from the window data area into guest memory (u64 loads only). */
105	static void win_load(void* dst, size_t woff, size_t len)
106	{
107	  unsigned char* d = (unsigned char*) dst;
108	  volatile const uint64_t* w = (volatile const uint64_t*) (WIN_DATA_VA + woff);
109	  while (len) {
110	    size_t n = len < 8 ? len : 8;
111	    uint64_t word = *w++;
112	    for (size_t i = 0; i < n; ++i)
113	      d[i] = (unsigned char) (word >> (8 * i));
114	    d += n;
115	    len -= n;
116	  }
117	}
118	
119	/* Stage a string at data-area offset `woff`; returns the byte offset just
120	 * past its NUL, rounded up to 8, or (size_t)-1 if it does not fit. */
121	static size_t win_store_str(size_t woff, const char* s)
122	{
123	  size_t len = 0;
124	  while (s[len])
125	    ++len;
126	  ++len; /* NUL */
127	  if (woff + len > WIN_DATA_SIZE)
128	    return (size_t) -1;
129	  win_store(woff, s, len);
130	  return (woff + len + 7) & ~(size_t) 7;
131	}
132	
133	/* One window syscall: stage the slots, ring the doorbell, read the result.
134	 * The doorbell write is an uncached device store, so the host has served
135	 * the call before the store retires; the fence orders the result load. */
136	static intptr_t win_syscall(uint64_t n, uint64_t a0, uint64_t a1, uint64_t a2,
137	                            uint64_t a3)
138	{
139	  WIN_SLOTS[0] = n;
140	  WIN_SLOTS[1] = a0;
141	  WIN_SLOTS[2] = a1;
142	  WIN_SLOTS[3] = a2;
143	  WIN_SLOTS[4] = a3;
144	  WIN_SLOTS[5] = 0;
145	  WIN_SLOTS[6] = 0;
146	  WIN_SLOTS[7] = 0;
147	  *(volatile uint32_t*) SYSCALL_GO_ADDR = 1;
148	  __asm__ __volatile__("fence rw,rw" ::: "memory");
149	  return (intptr_t) WIN_SLOTS[0];
150	}
151	
152	/* Marshaling helpers for the recurring shapes. */
153	
154	static intptr_t win_call_str(uint64_t n, const char* s, uint64_t a1,
155	                             uint64_t a2)
156	{
157	  if (win_store_str(0, s) == (size_t) -1)
158	    return -1;
159	  return win_syscall(n, WIN_DATA_VA, a1, a2, 0);
160	}
161	
162	static intptr_t win_call_str2(uint64_t n, const char* s0, const char* s1)
163	{
164	  size_t off1 = win_store_str(0, s0);
165	  if (off1 == (size_t) -1 || win_store_str(off1, s1) == (size_t) -1)
166	    return -1;
167	  return win_syscall(n, WIN_DATA_VA, WIN_DATA_VA + off1, 0, 0);
168	}
169	
170	/* ---- newlib stubs ------------------------------------------------------
171	 *
172	 * stat family note: the guest's struct bounces through the window BOTH
173	 * ways, so fields the host does not fill keep the caller's values (the
174	 * hosts write pico_stat's st_mode/st_size at their newlib offsets). */
175	
176	__attribute__((used)) ssize_t _write(int fd, const void* ptr, size_t len)
177	{
178	  if (fd > 2) {
179	    const unsigned char* p = (const unsigned char*) ptr;
180	    size_t done = 0;
181	    while (done < len) {
182	      size_t n = len - done;
183	      if (n > WIN_DATA_SIZE)
184	        n = WIN_DATA_SIZE;
185	      win_store(0, p + done, n);
186	      intptr_t r = win_syscall(VH_SYS_WRITE, fd, WIN_DATA_VA, n, 0);
187	      if (r < 0)
188	        return done ? (ssize_t) done : (ssize_t) r;
189	      done += (size_t) r;
190	      if ((size_t) r < n)
191	        break; /* short write */
192	    }
193	    return (ssize_t) done;
194	  }
195	  for (size_t i = 0; i < len; ++i)
196	    uart_putc(((const char*) ptr)[i]);
197	  return (ssize_t) len;
198	}
199	
200	__attribute__((used)) ssize_t _read(int fd, void* buf, size_t len)
201	{
202	  if (fd > 2) {
203	    unsigned char* p = (unsigned char*) buf;
204	    size_t done = 0;
205	    while (done < len) {
206	      size_t n = len - done;
207	      if (n > WIN_DATA_SIZE)
208	        n = WIN_DATA_SIZE;
209	      intptr_t r = win_syscall(VH_SYS_READ, fd, WIN_DATA_VA, n, 0);
210	      if (r < 0)
211	        return done ? (ssize_t) done : (ssize_t) r;
212	      if (r > 0)
213	        win_load(p + done, 0, (size_t) r);
214	      done += (size_t) r;
215	      if ((size_t) r < n)
216	        break; /* EOF or short read */
217	    }
218	    return (ssize_t) done;
219	  }
220	  return 0; /* no console input on either engine: EOF */
221	}
222	
223	__attribute__((used)) int _fstat(int fd, struct stat* st)
224	{
225	  if (fd > 2) {
226	    win_store(0, st, sizeof(*st));
227	    intptr_t ret = win_syscall(VH_SYS_FSTAT, fd, WIN_DATA_VA, 0, 0);
228	    if (ret == 0)
229	      win_load(st, 0, sizeof(*st));
230	    return (int) ret;
231	  }
232	  st->st_mode = S_IFCHR; /* char device -> newlib line-buffers stdout */
233	  return 0;
234	}
235	
236	__attribute__((used)) int _isatty(int fd) { return fd <= 2; }
237	
238	__attribute__((used)) int _close(int fd)
239	{
240	  if (fd > 2)
241	    return (int) win_syscall(VH_SYS_CLOSE, fd, 0, 0, 0);
242	  return 0;
243	}
244	
245	__attribute__((used)) off_t _lseek(int fd, off_t offset, int dir)
246	{
247	  if (fd > 2)
248	    return win_syscall(VH_SYS_LSEEK, fd, offset, dir, 0);
249	  return 0;
250	}
251	
252	__attribute__((used)) int _open(const char* name, int flags, int mode, ...)
253	{
254	  return (int) win_call_str(VH_SYS_OPEN, name, flags, mode);
255	}
256	
257	__attribute__((used)) int _openat(int dirfd, const char* name, int flags, ...)
258	{
259	  if (win_store_str(0, name) == (size_t) -1)
260	    return -1;
261	  return (int) win_syscall(VH_SYS_OPENAT, dirfd, WIN_DATA_VA, flags, 0);
262	}
263	
264	__attribute__((used)) int _stat(const char* file, struct stat* st)
265	{
266	  size_t stoff = win_store_str(0, file);
267	  if (stoff == (size_t) -1 || stoff + sizeof(*st) > WIN_DATA_SIZE)
268	    return -1;
269	  win_store(stoff, st, sizeof(*st));
270	  intptr_t ret =
271	    win_syscall(VH_SYS_STAT, WIN_DATA_VA, WIN_DATA_VA + stoff, 0, 0);
272	  if (ret == 0)
273	    win_load(st, stoff, sizeof(*st));
274	  return (int) ret;
275	}
276	
277	__attribute__((used)) int _lstat(const char* file, struct stat* st)
278	{
279	  size_t stoff = win_store_str(0, file);
280	  if (stoff == (size_t) -1 || stoff + sizeof(*st) > WIN_DATA_SIZE)
281	    return -1;
282	  win_store(stoff, st, sizeof(*st));
283	  intptr_t ret =
284	    win_syscall(VH_SYS_LSTAT, WIN_DATA_VA, WIN_DATA_VA + stoff, 0, 0);
285	  if (ret == 0)
286	    win_load(st, stoff, sizeof(*st));
287	  return (int) ret;
288	}
289	
290	__attribute__((used)) int _fstatat(int dirfd, const char* file,
291	                                   struct stat* st, int flags)
292	{
293	  size_t stoff = win_store_str(0, file);
294	  if (stoff == (size_t) -1 || stoff + sizeof(*st) > WIN_DATA_SIZE)
295	    return -1;
296	  win_store(stoff, st, sizeof(*st));
297	  intptr_t ret = win_syscall(VH_SYS_FSTATAT, dirfd, WIN_DATA_VA,
298	                             WIN_DATA_VA + stoff, flags);
299	  if (ret == 0)
300	    win_load(st, stoff, sizeof(*st));
301	  return (int) ret;
302	}
303	
304	__attribute__((used)) int _access(const char* file, int mode)
305	{
306	  return (int) win_call_str(VH_SYS_ACCESS, file, mode, 0);
307	}
308	
309	__attribute__((used)) int _faccessat(int dirfd, const char* file, int mode,
310	                                     int flags)
311	{
312	  if (win_store_str(0, file) == (size_t) -1)
313	    return -1;
314	  return (int) win_syscall(VH_SYS_FACCESSAT, dirfd, WIN_DATA_VA, mode, flags);
315	}
316	
317	__attribute__((used)) int _link(const char* oldn, const char* newn)
318	{
319	  return (int) win_call_str2(VH_SYS_LINK, oldn, newn);
320	}
321	
322	__attribute__((used)) int _unlink(const char* file)
323	{
324	  return (int) win_call_str(VH_SYS_UNLINK, file, 0, 0);
325	}
326	
327	__attribute__((used)) int _rename(const char* oldn, const char* newn)
328	{
329	  return (int) win_call_str2(VH_SYS_RENAME, oldn, newn);
330	}
331	
332	__attribute__((used)) int _getcwd(const char* buf, int size)
333	{
334	  size_t n = (size_t) size;
335	  if (n > WIN_DATA_SIZE)
336	    n = WIN_DATA_SIZE;
337	  intptr_t ret = win_syscall(VH_SYS_GETCWD, WIN_DATA_VA, n, 0, 0);
338	  if (ret != 0)
339	    win_load((void*) buf, 0, n);
340	  return (int) ret;
341	}
342	
343	__attribute__((used)) int _gettimeofday(struct timeval* tp, void* tzp)
344	{
345	  (void) tzp; /* both hosts ignore the timezone */
346	  intptr_t ret = win_syscall(VH_SYS_GETTIMEOFDAY, WIN_DATA_VA, 0, 0, 0);
347	  if (ret == 0) {
348	    /* The host writes {sec, usec} at the target's register width -- the
349	     * same bytes the legacy protocol wrote into the guest's struct. */
350	    win_load(tp, 0, __riscv_xlen == 64 ? 16 : 8);
351	  }
352	  return (int) ret;
353	}
354	
355	__attribute__((used)) int _kill(int pid, int sig)
356	{
357	  (void) pid;
358	  (void) sig;
359	  return -1;
360	}
361	
362	__attribute__((used)) int _getpid(void) { return 1; }
363	
364	__attribute__((used)) void* _sbrk(intptr_t increment)
365	{
366	  extern char _end[];
367	  static char* p = _end;
368	  void* base = p;
369	  p += increment;
370	  return base;
371	}
372	
373	/* Exit codes stay below 256: sim_control.hpp treats any command < 256 as
374	 * the raw exit code (the 0x0123456x magic commands live above). */
375	__attribute__((used, noreturn)) void _exit(int exit_status)
376	{
377	  *(volatile uint32_t*) SIM_EXIT_ADDR = (uint32_t) exit_status & 0xff;
378	  for (;;)
379	    ;
380	}
