30	// L2: keep at most this many failure bundles; older ones are pruned.
31	constexpr size_t kMaxReproBundles = 20;
32	
33	// Drop the oldest bundles (dir names start with a UTC timestamp, so the
34	// lexicographic order IS the age order) until at most `keep` remain.
35	void prune_repro_bundles(const fs::path& root, size_t keep) {
36	  std::error_code ec;
37	  std::vector<fs::path> dirs;
38	  for (const auto& e : fs::directory_iterator(root, ec))
39	    if (e.is_directory(ec)) dirs.push_back(e.path());
40	  if (dirs.size() <= keep) return;
41	  std::sort(dirs.begin(), dirs.end());  // oldest first
42	  for (size_t i = 0; i + keep < dirs.size(); ++i) fs::remove_all(dirs[i], ec);
43	}
