126	std::string qemu_cpu_from_cfg(const std::string& cfg_text) {
127	  // First `driver = "<cpu>-riscv-cpu"` global names the CPU model the cfg's
128	  // properties apply to; the fast leg must instantiate that same model.
129	  static const char kKey[] = "driver = \"";
130	  static const char kSuffix[] = "-riscv-cpu";
131	  for (size_t pos = cfg_text.find(kKey); pos != std::string::npos;
132	       pos = cfg_text.find(kKey, pos + 1)) {
133	    const size_t start = pos + sizeof(kKey) - 1;
134	    const size_t end = cfg_text.find('"', start);
135	    if (end == std::string::npos) break;
136	    const std::string driver = cfg_text.substr(start, end - start);
137	    const size_t suf = driver.rfind(kSuffix);
138	    if (suf != std::string::npos && suf + sizeof(kSuffix) - 1 == driver.size())
139	      return driver.substr(0, suf);
140	  }
141	  return "";
142	}
