224	std::vector<std::vector<std::string>> plan_argvs(
225	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
226	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
227	  std::vector<std::vector<std::string>> out;
228	  out.reserve(plan.steps.size());
229	  std::string prev_state_out;  // empty for the cold first leg
230	
231	  // hw-config sync: {vlen} comes from the hw-reference engine's descriptor
232	  // (the accurate-leg engine, or plan.hw_engine_id for the oracle plan).
233	  long vlen = 0;
234	  // LM content transport (ROADMAP_ilm_dlm F3) + HVM (ROADMAP_hvm F3): the
235	  // accurate engine's memory sizes (bytes, from its descriptor) arm the QEMU
236	  // plugin's sidecar drain and the vsim leg's --ilm/--dlm/--hvm backdoor
237	  // load. 0 = that engine has no such memory -> neither leg grows an arg.
238	  long ilm_size = 0, dlm_size = 0, hvm_size = 0;
239	  // Platform-cache (L2C/L3C) MMIO transport: the plugin's drain window
240	  // follows the ENGINE's register base (its --describe shared_cache_base).
241	  // 0 = the block is configured out of that RTL -> the plugin keeps its
242	  // default and the plan carries no token (the demo/sweep gate).
243	  long l2c_base = 0;
244	  if (const EngineDescriptor* e = plan_hw_engine(plan, engines)) {
245	    if (e->vlen > 0) vlen = e->vlen;
246	    if (e->ilm_size > 0) ilm_size = e->ilm_size;
247	    if (e->dlm_size > 0) dlm_size = e->dlm_size;
248	    if (e->hvm_size > 0) hvm_size = e->hvm_size;
249	    if (e->shared_cache_level > 0 && e->shared_cache_base > 0)
250	      l2c_base = e->shared_cache_base;
251	  }
252	  const std::string vlen_str = std::to_string(synced_vlen(vlen));
253	  std::string lm_suffix;
254	  if (ilm_size > 0) lm_suffix += ",ilm_size=" + std::to_string(ilm_size);
255	  if (dlm_size > 0) lm_suffix += ",dlm_size=" + std::to_string(dlm_size);
256	  if (hvm_size > 0) lm_suffix += ",hvm_size=" + std::to_string(hvm_size);
257	  if (l2c_base > 0) lm_suffix += ",l2c_base=" + std::to_string(l2c_base);
258	
259	  for (size_t i = 0; i < plan.steps.size(); ++i) {
260	    const Step& step = plan.steps[i];
261	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
262	    if (!eng) {
263	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
264	            step.engine_id + "'";
265	      return {};
266	    }
267	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
268	    if (!tmpl) {
269	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
270	            "' has no invoke template for role '" + step.role + "'";
271	      return {};
272	    }
273	
274	    std::string trig_err;
275	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
276	    if (!trig_err.empty()) {
277	      err = "plan step " + std::to_string(i) + ": " + trig_err;
278	      return {};
279	    }
280	
281	    const std::string state_out = state_path(workdir, i);
282	    // {plugin_args} is the qemu plugin comma-suffix: trigger args (empty for
283	    // marker) plus the LM sidecar-drain args (empty for a no-LM engine) plus
284	    // the forwarded log level (L4: one --log-level drives the whole pipeline).
285	    // {trigger} is its compatibility alias -- the name templates used before
286	    // non-trigger args joined the suffix (build_argv ignores unused keys).
287	    const std::string plugin_args = lt.plugin_suffix + lm_suffix +
288	                                    ",log_level=" +
289	                                    std::to_string(log_threshold());
290	    const std::map<std::string, std::string> m = {
291	        {"bin", eng->bin_path},
292	        {"elf", plan.elf},
293	        {"plugin", ctx.plugin_path},
294	        {"mmap", ctx.mmap_path},
295	        {"mmap_size", std::to_string(ctx.mem_size)},
296	        {"mmap_base", ctx.mmap_base},
297	        {"state_in", prev_state_out},
298	        {"state_out", state_out},
299	        {"plugin_args", plugin_args},
300	        {"trigger", plugin_args},
301	        {"vlen", vlen_str},
302	        // {qemu_cpu}: the model the readconfig globals target; the family
303	        // default when the engine has no --print-qemu-config hook.
304	        {"qemu_cpu", ctx.qemu_cpu.empty() ? kDefaultQemuCpu : ctx.qemu_cpu},
305	    };
306	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
307	    if (!err.empty()) {
308	      err = "plan step " + std::to_string(i) + ": " + err;
309	      return {};
310	    }
311	    // The QEMU producer leg loads the accurate engine's ISA via -readconfig (its
312	    // config.inc distilled to per-extension globals), so QEMU1 executes the same
313	    // extensions the engine models. Empty => keep the descriptor's default -cpu.
314	    if (step.role == "fast-leg" && !ctx.qemu_cfg.empty()) {
315	      argv.push_back("-readconfig");
316	      argv.push_back(ctx.qemu_cfg);
317	    }
318	    // LM content transport (F3): point the vsim leg at the sidecars its
319	    // producer drained next to state_in (--ilm/--dlm backdoor load).
320	    if (step.role == "accurate-leg") {
321	      if (ilm_size > 0) {
322	        argv.push_back("--ilm");
323	        argv.push_back(prev_state_out + ".ilm");
324	      }
325	      if (dlm_size > 0) {
326	        argv.push_back("--dlm");
327	        argv.push_back(prev_state_out + ".dlm");
328	      }
329	      if (hvm_size > 0) {
330	        argv.push_back("--hvm");
331	        argv.push_back(prev_state_out + ".hvm");
332	      }
333	    }
334	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
335	    // after the filled template (matches tests/e2e.sh's ordering).
336	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
337	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
338	    out.push_back(std::move(argv));
339	    prev_state_out = state_out;
340	  }
341	  err.clear();
342	  return out;
343	}
344	
345	PlanResult run_plan(const Plan& plan,
346	                    const std::vector<EngineDescriptor>& engines,
347	                    const PlanOptions& opts) {
348	  PlanResult res;
349	  if (plan.steps.empty()) {
350	    res.error = "plan has no steps";
351	    return res;
352	  }
353	
354	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
355	  std::string mmap_path = plan.mmap_path;
356	  const bool own_mmap = mmap_path.empty();
357	  if (own_mmap) {
358	    std::string err;
359	    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
360	    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
361	    if (mmap_path.empty()) {
362	      res.error = err;
363	      return res;
364	    }
365	  }
366	
367	  // A private dir for the threaded drain files.
368	  std::error_code ec;
369	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
370	  std::string tmpl = workdir.string();
371	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
372	  tbuf.push_back('\0');
373	  const char* made = ::mkdtemp(tbuf.data());
374	  if (!made) {
375	    if (own_mmap) ::unlink(mmap_path.c_str());
376	    res.error = "failed to create plan work dir";
377	    return res;
378	  }
379	  const std::string wd = made;
380	
381	  RuntimeCtx ctx;
382	  ctx.mmap_path = mmap_path;
383	  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
384	  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
385	  // linker script still uses only --mem-size, so the scratch page sits above
386	  // everything it can address.
387	  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
388	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
389	
390	  // Match the QEMU producer leg's ISA to the hw-reference engine (the
391	  // accurate-leg engine, or plan.hw_engine_id for the --verify oracle plan):
392	  // ask that engine for a QEMU -readconfig cfg distilled from its config.inc.
393	  // Tolerant -- an engine without --print-qemu-config leaves qemu_cfg empty
394	  // (the parser throws on the unknown flag -> non-zero exit), so the fast leg
395	  // keeps its -cpu.
396	  if (const EngineDescriptor* e = plan_hw_engine(plan, engines);
397	      e && !e->bin_path.empty()) {
398	    const RunResult probe =
399	        run_process({e->bin_path, "--print-qemu-config"}, kQemuCfgProbeMs);
400	    ctx.qemu_cfg = stage_qemu_cfg(wd, probe);
401	    // The cfg's globals only apply to the CPU driver they name, so the
402	    // fast leg instantiates that same model ({qemu_cpu} fill).
403	    if (!ctx.qemu_cfg.empty()) ctx.qemu_cpu = qemu_cpu_from_cfg(probe.out);
404	  }
405	
406	  std::string err;
407	  const std::vector<std::vector<std::string>> argvs =
408	      plan_argvs(plan, engines, wd, ctx, err);
409	  if (!err.empty()) {
410	    res.error = err;
411	  } else if (opts.dry_run) {
412	    // Build-only: the argvs are fully resolved (placeholders, staged qemu_cfg,
413	    // threaded state paths) -- record them for the caller to print, spawn none.
414	    res.argvs = argvs;
415	  } else {
416	    res.argvs = argvs;
417	    // A failing leg keeps the evidence (L2) next to its error.
418	    const auto fail_step = [&](size_t i, const std::string& msg) {
419	      res.error = msg;
420	      res.repro_dir = save_repro_bundle(wd, plan, argvs, i, msg);
421	    };
422	    for (size_t i = 0; i < argvs.size(); ++i) {
423	      // trace: the fully resolved command, copy-pasteable to re-run this leg.
424	      log_line(kLogTrace, "[andesim] exec %s [%s]: %s",
425	               plan.steps[i].role.c_str(), plan.steps[i].engine_id.c_str(),
426	               render_argv(argvs[i]).c_str());
427	      // At debug the legs' stderr streams through live (vsim's own leveled
428	      // log, the plugin's drain summary); at info and above it stays dropped.
429	      const RunResult r =
430	          run_process(argvs[i], opts.timeout_ms, log_on(kLogDebug));
431	      if (r.spawn_failed) {
432	        fail_step(i, "plan step " + std::to_string(i) + ": failed to spawn");
433	        break;
434	      }
435	      if (r.timed_out) {
436	        fail_step(i, "plan step " + std::to_string(i) + ": timed out after " +
437	                         std::to_string(opts.timeout_ms) + " ms");
438	        break;
439	      }
440	      if (r.rc != opts.expect_rc) {
441	        fail_step(i, plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc));
442	        break;
443	      }
444	      const StateFile sf = read_state_file(state_path(wd, i));
445	      if (!sf.ok()) {
446	        fail_step(i, "plan step " + std::to_string(i) + ": " + sf.error);
447	        break;
448	      }
449	      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out, sf.st});
450	    }
451	  }
452	
453	  fs::remove_all(wd, ec);
454	  if (own_mmap) ::unlink(mmap_path.c_str());
455	  return res;
456	}
457	
458	}  // namespace andes_sim
