130	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
131	// exit code propagates. The per-model engine + selection are resolved by the
132	// caller; `model` here only labels the positional diagnostics.
133	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
134	                   const char* model, const std::vector<std::string>& extra = {},
135	                   bool clean_output = false) {
136	  if (int rc = check_one_elf(cli, model)) return rc;
137	  // QEMU's -bios flag searches its data directory for relative paths rather
138	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
139	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
140	  if (elf.empty()) return 2;
141	  std::vector<std::string> args = extra;
142	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
